input.command:
cd /home/user/fortress-comprises && mkdir -p tmp/sk/substFix/src && python3 - <<'EOF'
import io
F='ProjectFortress/src/com/sun/fortress/scala_src/typechecker/TypeHierarchyChecker.scala'
s=io.open(F,encoding='utf-8').read()
a="""    val subs = analyzer.traits.iterator.toList.collect{ case ti: TraitIndex => ti }.filter(ti =>
      toListFromImmutable(ti.extendsTypes).exists(tw => tw.getBaseType match {
        case st: TraitType => st.getName.getText.equals(tt.getName.getText)
        case _ => false }))
    subs.nonEmpty && subs.forall(ti => toOption(ti.typeOfSelf) match {
      case Some(self) => SNodeUtil.getTraitType(self) match {
        case Some(sub) => comprisesContains(comprises, sub,
			    analyzer.extend(toListFromImmutable(ti.staticParameters), None))
        case _ => false }
      case _ => false })"""
b="""    val tparams = analyzer.typeCons(tt.getName) match {
      case gi: TraitIndex => toListFromImmutable(gi.staticParameters)
      case _ => List() }
    val subs = analyzer.traits.iterator.toList.collect{ case ti: TraitIndex => ti }.flatMap(ti =>
      toListFromImmutable(ti.extendsTypes).flatMap(tw => tw.getBaseType match {
        case st: TraitType if st.getName.getText.equals(tt.getName.getText) => List((ti, st))
        case _ => List() }))
    subs.nonEmpty && subs.forall(p => toOption(p._1.typeOfSelf) match {
      case Some(self) => SNodeUtil.getTraitType(self) match {
        case Some(sub) => comprisesContains(
			    comprises.map(c => substitute(toListFromImmutable(p._2.getArgs), tparams, c).asInstanceOf[NamedType]),
			    sub, analyzer.extend(toListFromImmutable(p._1.staticParameters), None))
        case _ => false }
      case _ => false })"""
assert s.count(a)==1
io.open('tmp/sk/substFix/src/TypeHierarchyChecker.scala','w',encoding='utf-8').write(s.replace(a,b))
EOF
source tmp/sk/env.sh; CP=$(bin/fortress_classpath | tail -1); rm -rf $SK/substFix/cls; mkdir -p $SK/substFix/cls; java -Xmx1g -cp "$SCP" scala.tools.nsc.Main -d $SK/substFix/cls -classpath "$CP" -encoding UTF-8 $SK/substFix/src/TypeHierarchyChecker.scala 2>&1 | tail -5; ls $SK/substFix/cls/com/sun/fortress/scala_src/typechecker/

